txt_input = ''''''

POTIONS_NEEDED_MAP = {
    'x': 0,
    'A': 0,
    'B': 1,
    'C': 3,
    'D': 5,
}

def potions_needed(txt_input):
    total = 0
    for c in txt_input:
        total += POTIONS_NEEDED_MAP[c]
    return total


print(potions_needed("ABBAC"))
print(potions_needed(txt_input))


def potions_needed_part2(txt_input):
    total = 0
    for c, d in zip(txt_input[::2], txt_input[1::2]):
        total += POTIONS_NEEDED_MAP[c]
        total += POTIONS_NEEDED_MAP[d]
        if c != 'x' and d != 'x':
            total += 2

    return total

part2_input = ''''''
print(potions_needed_part2("AxBCDDCAxD"))
print(potions_needed_part2(part2_input))


def potions_needed_part3(txt_input):
    total = 0
    for c, d, e in zip(txt_input[::3], txt_input[1::3], txt_input[2::3]):
        total += POTIONS_NEEDED_MAP[c]
        total += POTIONS_NEEDED_MAP[d]
        total += POTIONS_NEEDED_MAP[e]
        if [c, d,e ].count("x") == 1:
            total += 2
        if [c, d,e ].count("x") == 0:
            total += 6

    return total

part2_input = ''''''
print(potions_needed_part3("xBxAAABCDxCC"))
print(potions_needed_part3(part2_input))
